import { chromium } from 'playwright'

const OUT = 'C:/Users/Administrator/AppData/Local/Temp/ogflow-verify.png'
const browser = await chromium.launch({ headless: true })
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
await ctx.addInitScript(() => {
  sessionStorage.setItem('Admin-Token', 'e2e-mock-token')
  sessionStorage.setItem('Portal-UserId', '90001')
})
const page = await ctx.newPage()
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
await page.goto('http://127.0.0.1:8092/#/operation-guide?line=commercial&tab=developer', { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.og-flow-card', { timeout: 20000 })
await page.evaluate(() => document.fonts.ready)

const data = await page.evaluate(() => {
  const q = (s) => Array.from(document.querySelectorAll(s))
  const cards = q('.og-flow-card')
  const txt = (el, sel) => (el.querySelector(sel) ? el.querySelector(sel).textContent.trim() : '')
  const rows = q('.og-flow-row')
  const btn = document.querySelector('.og-flow-action')
  const first = cards[0]
  return {
    url: location.href,
    og: !!document.querySelector('.operation-guide'),
    cardCount: cards.length,
    titles: cards.map((c) => txt(c, '.og-flow-card-title')),
    bodies: cards.map((c) => txt(c, '.og-flow-card-body')),
    rowsCounts: rows.map((r) => r.querySelectorAll('.og-flow-card').length),
    arrowsPerRow: rows.map((r) => r.querySelectorAll('.og-flow-arrow').length),
    buttonText: btn ? btn.textContent.trim() : null,
    calloutGone: q('.og-callout').length === 0,
    topBorder: first ? getComputedStyle(first).borderTopColor : null,
    badgeBg: first && first.querySelector('.og-flow-card-index') ? getComputedStyle(first.querySelector('.og-flow-card-index')).backgroundColor : null
  }
})
await page.screenshot({ path: OUT, fullPage: true, animations: 'disabled' })
console.log(JSON.stringify({ data, errors }))
await browser.close()
